import numpy as np

# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: This is a simple implementation of a randomized algorithm for the GNBG black-box minimization benchmark.
# Search state: The algorithm maintains a single candidate solution.
# Candidate generation: New candidates are generated by perturbing the current solution with Gaussian noise.
# Selection and replacement: The current solution is replaced if a new candidate is found with a lower objective value.
# Adaptation: The standard deviation of the Gaussian noise is adapted based on the success rate of the search.
# Exploration mechanisms: The algorithm explores the search space by generating new candidates using Gaussian noise.
# Exploitation mechanisms: The algorithm exploits the current solution by perturbing it to find better solutions.
# Boundary handling: Candidate solutions that violate the problem bounds are projected back onto the feasible region.
# Budget strategy: The algorithm uses the entire evaluation budget to search for the optimal solution.
# Closest known influences: This algorithm is inspired by simple stochastic local search methods, such as randomized hill climbing.
# Novelty or unusual aspects: The algorithm is designed to be compact, robust, and easy to understand, without any specialized mechanisms.
# Failure modes: The algorithm may struggle to solve problems with highly multimodal or deceptive objective functions, or problems with a large number of local minima.
# ALGORITHM_ANALYSIS_NOTE_END

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim
        self.x = np.random.uniform(low=-5, high=5, size=self.dim)
        self.sigma = 1.0
        self.success_count = 0
        self.total_count = 0

    def __call__(self, func):
        best_x = self.x.copy()
        best_y = func(best_x)

        for _ in range(self.budget):
            # Generate a new candidate solution
            candidate = self.x + np.random.normal(0, self.sigma, size=self.dim)

            # Ensure the candidate is within the problem bounds
            candidate = np.clip(candidate, func.lower, func.upper)

            # Evaluate the new candidate
            candidate_y = func(candidate)

            # Update the best solution if the new candidate is better
            if candidate_y < best_y:
                best_x = candidate.copy()
                best_y = candidate_y

            # Update the search state
            self.x = candidate.copy()
            self.total_count += 1

            # Adapt the step size based on the success rate
            if candidate_y < func(self.x):
                self.success_count += 1
            self.sigma = max(0.1, self.sigma * (1 + 0.1 * (self.success_count / self.total_count - 0.2)))

        return best_x, best_y
